import{_ as r,o as t,c as a,ae as e}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-02","description":"","frontmatter":{"date":"2026-07-02T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-02-product.md","filePath":"daily/2026-07-02-product.md"}'),n={name:"daily/2026-07-02-product.md"};function s(p,o,i,g,l,h){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="产品发布-2026-07-02" tabindex="-1">产品发布 - 2026-07-02 <a class="header-anchor" href="#产品发布-2026-07-02" aria-label="Permalink to &quot;产品发布 - 2026-07-02&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日AI产品领域动态聚焦于功能更新和效率提升。Notion AI集成GLM 5.2模型，提升图像生成能力；数字.ai发布23.3版本，简化应用部署；Product Copilot和微软Copilot作为AI助手，分别在Jira/Confluence和组织层面提高效率。最值得关注的是Notion AI的新模型集成和微软Copilot的聊天式AI工具。</p><hr><h3 id="_1-notion-ai功能更新与新特性" tabindex="-1">1. Notion AI功能更新与新特性 <a class="header-anchor" href="#_1-notion-ai功能更新与新特性" aria-label="Permalink to &quot;1. Notion AI功能更新与新特性&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features</a></p><p><strong>一句话摘要</strong>: Notion AI提升图像生成限制并集成GLM 5.2模型</p><p><strong>能解决什么问题</strong>: 解决用户在设计工作中对图像生成和多平台文件搜索的需求</p><p><strong>产品应用</strong>: 适用于需要集中设计和跨平台文件管理的实际产品中</p><p><strong>示例场景</strong>: 设计师在Notion中快速迭代页面视觉设计</p><hr><h3 id="_2-notion文档更新日志" tabindex="-1">2. Notion文档更新日志 <a class="header-anchor" href="#_2-notion文档更新日志" aria-label="Permalink to &quot;2. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion扩展AI助手功能并发布新SDK版本</p><p><strong>能解决什么问题</strong>: 提高Notion AI助手的数据库查询能力和API的易用性</p><p><strong>产品应用</strong>: 适用于需要集成Notion数据库和AI助手的企业团队</p><p><strong>示例场景</strong>: 企业团队使用AI助手直接查询数据库</p><hr><h3 id="_3-数字-ai发布23-3-工作流概览" tabindex="-1">3. 数字.ai发布23.3：工作流概览 <a class="header-anchor" href="#_3-数字-ai发布23-3-工作流概览" aria-label="Permalink to &quot;3. 数字.ai发布23.3：工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai发布23.3引入自助服务工作流简化应用部署。</p><p><strong>能解决什么问题</strong>: 降低开发者使用工具的复杂性，提高云应用性能和可靠性。</p><p><strong>产品应用</strong>: 适用于需要自动化部署和优化云应用的软件开发团队。</p><p><strong>示例场景</strong>: 开发团队使用工作流自动化CI/CD流程。</p><hr><h3 id="_4-产品副驾驶——软件产品团队的ai助手" tabindex="-1">4. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_4-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;4. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，提高产品管理效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在票务管理、协作和文档更新中的效率和一致性问题。</p><p><strong>产品应用</strong>: 适用于需要优化产品管理流程的软件团队，直接在Jira和Confluence中使用。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot创建清晰工单，清理积压任务。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软推出基于聊天的生成式AI工具，助力组织和个人提高效率。</p><p><strong>能解决什么问题</strong>: 提升组织和个人的工作效率，同时保障企业级安全和隐私。</p><p><strong>产品应用</strong>: 可应用于日常办公、安全运维、编程等领域，通过AI助手提升工作效能。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot快速完成文档编辑和数据分析。</p><hr><h3 id="_6-微软副驾驶" tabindex="-1">6. 微软副驾驶 <a class="header-anchor" href="#_6-微软副驾驶" aria-label="Permalink to &quot;6. 微软副驾驶&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot</a></p><p><strong>一句话摘要</strong>: 微软推出基于大型语言模型的智能聊天机器人。</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供更智能的虚拟助手服务。</p><p><strong>产品应用</strong>: 可以集成到Windows和Microsoft 365，提升工作效率。</p><p><strong>示例场景</strong>: 使用Copilot Studio创建定制的AI助手。</p><hr><h3 id="_7-ai新闻-导致市场崩溃的ai产品发布" tabindex="-1">7. AI新闻：导致市场崩溃的AI产品发布 <a class="header-anchor" href="#_7-ai新闻-导致市场崩溃的ai产品发布" aria-label="Permalink to &quot;7. AI新闻：导致市场崩溃的AI产品发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=xdp8bulnidY&amp;vl=en-US" target="_blank" rel="noreferrer">AI News: The AI Launch That Crashed The Market - YouTube</a></p><p><strong>一句话摘要</strong>: 本周AI领域发生了许多重大新闻和产品发布。</p><p><strong>能解决什么问题</strong>: 提供AI新闻、产品更新和模型升级的最新信息。</p><p><strong>产品应用</strong>: 可以应用于AI新闻报道和产品开发，提供最新动态。</p><p><strong>示例场景</strong>: 开发者使用Codex app进行编程和代码协作。</p><hr><h3 id="_8-谷歌推出完全由ai驱动的搜索引擎-重新构想网络工具" tabindex="-1">8. 谷歌推出完全由AI驱动的搜索引擎，重新构想网络工具 <a class="header-anchor" href="#_8-谷歌推出完全由ai驱动的搜索引擎-重新构想网络工具" aria-label="Permalink to &quot;8. 谷歌推出完全由AI驱动的搜索引擎，重新构想网络工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uk.finance.yahoo.com/news/google-launches-fully-ai-powered-180114643.html" target="_blank" rel="noreferrer">Google launches fully AI-powered search engine in ‘reimagining’ of web tool</a></p><p><strong>一句话摘要</strong>: 谷歌发布AI版搜索引擎，允许更复杂查询和深入话题探讨</p><p><strong>能解决什么问题</strong>: 解决传统搜索引擎无法处理复杂和长查询的问题</p><p><strong>产品应用</strong>: 可应用于实际产品，通过AI提升搜索深度和个性化体验</p><p><strong>示例场景</strong>: 用户可以深入查询特定主题，获得更详细答案</p><hr><h3 id="_9-谷歌推出全新ai搜索模式" tabindex="-1">9. 谷歌推出全新AI搜索模式 <a class="header-anchor" href="#_9-谷歌推出全新ai搜索模式" aria-label="Permalink to &quot;9. 谷歌推出全新AI搜索模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=X8n7ezdYuK4" target="_blank" rel="noreferrer">Google Launches a BRAND NEW AI Search?!</a></p><p><strong>一句话摘要</strong>: 谷歌推出AI Mode，挑战传统搜索和SEO。</p><p><strong>能解决什么问题</strong>: 应对新兴AI搜索工具对传统搜索的威胁。</p><p><strong>产品应用</strong>: 适用于快速适应的业务，改变数字营销和SEO策略。</p><p><strong>示例场景</strong>: 美国付费AI计划用户测试AI Mode进行搜索优化。</p><hr><h3 id="_10-openai推出ai驱动搜索引擎-可能挑战谷歌" tabindex="-1">10. OpenAI推出AI驱动搜索引擎，可能挑战谷歌 <a class="header-anchor" href="#_10-openai推出ai驱动搜索引擎-可能挑战谷歌" aria-label="Permalink to &quot;10. OpenAI推出AI驱动搜索引擎，可能挑战谷歌&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.forbes.com/sites/tylerroush/2024/10/31/openai-launches-ai-powered-search-engine-that-could-challenge-google-heres-what-to-know" target="_blank" rel="noreferrer">OpenAI Launches AI-Powered Search Engine—Here’s What To Know</a></p><p><strong>一句话摘要</strong>: OpenAI将AI搜索引擎集成到ChatGPT中，可能改变互联网搜索市场格局。</p><p><strong>能解决什么问题</strong>: 解决传统搜索引擎信息过载和信息筛选效率低的问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过AI技术提供更精准的搜索结果和信息摘要。</p><p><strong>示例场景</strong>: 用户查询特定地区音乐活动，得到活动列表和链接。</p><hr>',75)])])}const u=r(n,[["render",s]]);export{d as __pageData,u as default};
